// Statement — static SQL, no parameters
Statement stmt = connection.createStatement();
ResultSet rs1 = stmt.executeQuery("SELECT COUNT(*) FROM orders");

// PreparedStatement — parameterized SQL, prevents injection
PreparedStatement pstmt = connection.prepareStatement(
    "SELECT * FROM customers WHERE email = ?");
pstmt.setString(1, userEmail); // parameter index starts at 1
ResultSet rs2 = pstmt.executeQuery();

// CallableStatement — stored procedure call
CallableStatement cstmt = connection.prepareCall(
    "{call calculate_order_total(?, ?)}");
cstmt.setLong(1, orderId); // IN parameter
cstmt.registerOutParameter(2, Types.DECIMAL); // OUT parameter
cstmt.execute();
BigDecimal total = cstmt.getBigDecimal(2); // retrieve OUT value

// Always close resources
rs1.close(); stmt.close();
rs2.close(); pstmt.close();
cstmt.close();

// VULNERABLE: Statement with concatenation
String userInput = "alice@example.com' OR '1'='1"; // malicious input
String sql = "SELECT * FROM customers WHERE email = '" + userInput + "'";
// Actual SQL executed:
// SELECT * FROM customers WHERE email = 'alice@example.com' OR '1'='1'
// The OR clause is always true — returns ALL customers!
Statement stmt = connection.createStatement();
ResultSet rs = stmt.executeQuery(sql); // attacker sees all data

// SAFE: PreparedStatement with parameterization
String safeInput = "alice@example.com' OR '1'='1"; // same input
PreparedStatement pstmt = connection.prepareStatement(
    "SELECT * FROM customers WHERE email = ?");
pstmt.setString(1, safeInput); // entire string treated as literal email
// Database searches for an email that literally equals "alice@example.com' OR '1'='1"
// No rows match — the single quotes are escaped automatically
ResultSet rs2 = pstmt.executeQuery(); // safe, returns nothing

// Statement — database re-parses and re-plans every time
Statement stmt = connection.createStatement();
for (int i = 0; i < 1000; i++) {
    String sql = "INSERT INTO orders (customer_id, amount) VALUES (" 
                 + customerId + ", " + amounts[i] + ")";
    stmt.executeUpdate(sql); // full parse-plan-execute cycle × 1000
}

// PreparedStatement — database parses and plans once
PreparedStatement pstmt = connection.prepareStatement(
    "INSERT INTO orders (customer_id, amount) VALUES (?, ?)");
for (int i = 0; i < 1000; i++) {
    pstmt.setLong(1, customerId);
    pstmt.setBigDecimal(2, amounts[i]);
    pstmt.executeUpdate(); // reuses cached plan, only executes
}
// Result: PreparedStatement is 2-10x faster depending on query complexity

// PostgreSQL procedure: CREATE PROCEDURE calculate_discount(IN order_id BIGINT, OUT discount DECIMAL)
// Procedure calculates discount based on order total and customer tier

CallableStatement cstmt = connection.prepareCall(
    "{call calculate_discount(?, ?)}");

// Set IN parameter — order ID
cstmt.setLong(1, 12345L);

// Register OUT parameter — discount amount
cstmt.registerOutParameter(2, Types.DECIMAL);

// Execute the procedure
cstmt.execute();

// Retrieve OUT parameter value
BigDecimal discount = cstmt.getBigDecimal(2);
System.out.println("Calculated discount: " + discount);

cstmt.close();

// In a Spring Boot app with HikariCP connection pool
// Connection pool initializes connections on startup

// First request — PreparedStatement created and compiled
Connection conn = dataSource.getConnection(); // from pool
PreparedStatement pstmt = conn.prepareStatement(
    "SELECT * FROM orders WHERE customer_id = ? AND status = ?");
// Database parses SQL, builds execution plan, caches it
pstmt.setLong(1, 101L);
pstmt.setString(2, "PENDING");
ResultSet rs = pstmt.executeQuery(); // full parse-plan-execute

// Second request — same pooled connection, same PreparedStatement
pstmt.setLong(1, 202L);
pstmt.setString(2, "SHIPPED");
ResultSet rs2 = pstmt.executeQuery(); // reuses cached plan, only executes

// After 5+ executions, PostgreSQL promotes to server-side prepared statement
// Plan is permanently cached for this connection until it's closed

// PostgreSQL function: CREATE FUNCTION apply_loyalty_discount(order_id BIGINT, OUT final_amount DECIMAL)
// Function calculates final order amount after applying customer loyalty discount

// Step 1: Prepare the callable statement with JDBC escape syntax
CallableStatement cstmt = connection.prepareCall(
    "{call apply_loyalty_discount(?, ?)}");

// Step 2: Set input parameter (IN) — order ID
cstmt.setLong(1, 98765L);

// Step 3: Register output parameter (OUT) — final amount
cstmt.registerOutParameter(2, Types.DECIMAL);

// Step 4: Execute the stored procedure
cstmt.execute();

// Step 5: Retrieve output parameter value
BigDecimal finalAmount = cstmt.getBigDecimal(2);
System.out.println("Final discounted amount: $" + finalAmount);

// Always close the statement
cstmt.close();
